{
  "title": "封印妖孽",
  "scene": "在一座古老而神秘的山峰之巅，云雾缭绕，山石之间隐约可见一尊巨大的石像，石像正中央有一个被冰雪覆盖的洞穴，洞穴中传来诡异的低吟声。玩家需要找到封印妖孽的机关，才能恢复山中和平安宁。",
  "goal": "解开石像的秘密，找到封印妖孽的机关，让妖孽重新被封印。",
  "choices": [
    {
      "id": "A",
      "text": "靠近洞穴，仔细观察洞穴内部。",
      "outcome": "玩家发现洞穴内部有一个被封印的妖怪，但无法直接触碰它，需寻找线索。",
      "result": "partial",
      "next": "B"
    },
    {
      "id": "B",
      "text": "尝试用石头砸碎洞穴周围结冰的石壁。",
      "outcome": "玩家发现石壁中有机关，但附近没有可以砸碎的物品，此方法无效。",
      "result": "fail",
      "next": "C"
    },
    {
      "id": "C",
      "text": "仔细观察石像周围的刻痕，试图找到与洞穴内部妖怪相关的线索。",
      "outcome": "玩家发现刻痕中隐含着一个机关，通过解读刻痕，找到了解锁洞穴的咒语。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
